#include <stdint.h>

extern uint32_t _estack;
extern uint32_t _sidata;
extern uint32_t _sdata;
extern uint32_t _edata;
extern uint32_t _sbss;
extern uint32_t _ebss;

extern int main(void);

void Reset_Handler(void);
void Default_Handler(void);

void NMI_Handler(void)        __attribute__((weak, alias("Default_Handler")));
void HardFault_Handler(void)  __attribute__((weak, alias("Default_Handler")));
void MemManage_Handler(void)  __attribute__((weak, alias("Default_Handler")));
void BusFault_Handler(void)   __attribute__((weak, alias("Default_Handler")));
void UsageFault_Handler(void) __attribute__((weak, alias("Default_Handler")));
void SVC_Handler(void)        __attribute__((weak, alias("Default_Handler")));
void DebugMon_Handler(void)   __attribute__((weak, alias("Default_Handler")));
void PendSV_Handler(void)     __attribute__((weak, alias("Default_Handler")));
void SysTick_Handler(void)    __attribute__((weak, alias("Default_Handler")));

__attribute__((section(".isr_vector"), used))
const uint32_t *vector_table[] = {
    (uint32_t *)&_estack,
    (uint32_t *)Reset_Handler,
    (uint32_t *)NMI_Handler,
    (uint32_t *)HardFault_Handler,
    (uint32_t *)MemManage_Handler,
    (uint32_t *)BusFault_Handler,
    (uint32_t *)UsageFault_Handler,
    0, 0, 0, 0,
    (uint32_t *)SVC_Handler,
    (uint32_t *)DebugMon_Handler,
    0,
    (uint32_t *)PendSV_Handler,
    (uint32_t *)SysTick_Handler
};

void Reset_Handler(void) {
    uint32_t *src = &_sidata;
    uint32_t *dst = &_sdata;
    while (dst < &_edata) {
        *dst++ = *src++;
    }

    dst = &_sbss;
    while (dst < &_ebss) {
        *dst++ = 0;
    }

    main();

    while (1) {}
}

void Default_Handler(void) {
    while (1) {}
}

#include <stdint.h>

/* Địa chỉ thanh ghi từ CMSIS-STM32F469XX-H */
#define PERIPH_BASE           (0x40000000UL)
#define AHB1PERIPH_BASE       (PERIPH_BASE + 0x00020000UL)

/* RCC: 0x40023800 */
#define RCC_BASE              (AHB1PERIPH_BASE + 0x3800UL)
#define RCC_AHB1ENR           (*(volatile uint32_t *)(RCC_BASE + 0x30UL))
#define RCC_AHB1ENR_GPIOGEN   (1UL << 6)

/* GPIOG: 0x40021800 */
#define GPIOG_BASE            (AHB1PERIPH_BASE + 0x1800UL)
#define GPIOG_MODER           (*(volatile uint32_t *)(GPIOG_BASE + 0x00UL))
#define GPIOG_ODR             (*(volatile uint32_t *)(GPIOG_BASE + 0x14UL))
#define GPIOG_BSRR            (*(volatile uint32_t *)(GPIOG_BASE + 0x18UL))

/* LED1 (Green) nối vào chân PG6 (tài liệu BSP-STM32469I-DISCO-H dòng 131, 145) */
#define LED1_PIN              (6U)

static void delay_cycles(volatile uint32_t count) {
    while (count--) {
        __asm__ volatile ("nop");
    }
}

int main(void) {
    /* 1. Bật clock cho cổng GPIOG */
    RCC_AHB1ENR |= RCC_AHB1ENR_GPIOGEN;

    /* 2. Cấu hình PG6 thành General Purpose Output mode (MODER[13:12] = 01b) */
    GPIOG_MODER &= ~(3UL << (LED1_PIN * 2));
    GPIOG_MODER |=  (1UL << (LED1_PIN * 2));

    /* 3. Vòng lặp chính: đảo trạng thái đèn LED1 với chu kỳ ~0.5s */
    while (1) {
        /* Bật LED1 */
        GPIOG_BSRR = (1UL << LED1_PIN);
        delay_cycles(1000000);

        /* Tắt LED1 */
        GPIOG_BSRR = (1UL << (LED1_PIN + 16));
        delay_cycles(1000000);
    }

    return 0;
}

