/* 0x53: WRCTRLD - bat BCTRL (0x2C: BCTRL=1, DD=1, BL=1) */
HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P1, 0x53, 0x2C);
/* 0x29: Display On */
HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P0, 0x29, 0x00);
HAL_Delay(50);

