extern int32_t DSI_IO_ReadCmd(uint32_t Reg, uint8_t *pData, uint32_t Size);

static int32_t bsp_otm8009a_write(uint16_t Addr, uint16_t Reg, uint8_t *pData, uint16_t Length)
{
  (void)Addr;
  uint8_t buf[64];
  buf[0] = (uint8_t)Reg;
  if (Length > 0 && pData != NULL) {
    if (Length > 60) Length = 60;
    for (uint16_t i = 0; i < Length; i++) {
      buf[i + 1] = pData[i];
    }
    DSI_IO_WriteCmd(Length, buf);
  } else {
    buf[1] = 0;
    DSI_IO_WriteCmd(0, buf);
  }
  return 0;
}

